/// Look up the static message catalog for a locale.
pub const fn for_locale(locale: Locale) -> &'static Catalog {
    match locale {
        Locale::En => &EN,
        Locale::De => &DE,
        Locale::Es => &ES,
        Locale::Fr => &FR,
        Locale::It => &IT,
        Locale::PtBr => &PTBR,
        Locale::Nl => &NL,
        Locale::Ru => &RU,
        Locale::Uk => &UK,
        Locale::Ja => &JA,
        Locale::Ko => &KO,
        Locale::ZhCn => &ZHCN,
        Locale::ZhTw => &ZHTW,
        Locale::Ar => &AR,
        Locale::Hi => &HI,
        Locale::Pl => &PL,
        Locale::Tr => &TR,
        Locale::Sv => &SV,
        Locale::Vi => &VI,
        Locale::Id => &ID,
        Locale::AfZa => &AFZA,
        Locale::AmEt => &AMET,
        Locale::ArEg => &AREG,
        Locale::ArMa => &ARMA,
        Locale::FrMa => &FRMA,
        Locale::FrSn => &FRSN,
        Locale::HaNg => &HANG,
        Locale::IgNg => &IGNG,
        Locale::MgMg => &MGMG,
        Locale::RwRw => &RWRW,
        Locale::SoSo => &SOSO,
        Locale::SwKe => &SWKE,
        Locale::XhZa => &XHZA,
        Locale::YoNg => &YONG,
        Locale::ZuZa => &ZUZA,
        Locale::Bn => &BN,
        Locale::Fa => &FA,
        Locale::He => &HE,
        Locale::Mr => &MR,
        Locale::Ta => &TA,
        Locale::Te => &TE,
        Locale::Th => &TH,
        Locale::Ur => &UR,
        Locale::Ms => &MS,
        Locale::Fil => &FIL,
        Locale::Bs => &BS,
        Locale::Hr => &HR,
        Locale::Sr => &SR,
    }
}

